SELECT c.*, UNIX_TIMESTAMP(c.open_time) AS open_epoch_utc FROM crypto_ai.candle c WHERE (c.interval_code='5m' AND ((c.symbol='EGLDUSDT' AND c.open_time IN ('2026-10-11 20:50:00','2026-10-11 22:30:00','2026-10-11 22:35:00')) OR (c.symbol='XRPUSDT' AND c.open_time='2026-10-12 02:30:00') OR (c.symbol='DOGEUSDT' AND c.open_time='2026-10-12 03:55:00') OR (c.symbol='SHIBUSDT' AND c.open_time='2026-10-12 06:30:00') OR (c.symbol='ACEUSDT' AND c.open_time='2026-10-12 09:50:00'))) OR (c.interval_code='1h' AND ((c.symbol='EGLDUSDT' AND c.open_time IN ('2026-10-11 19:00:00','2026-10-11 21:00:00')) OR (c.symbol='XRPUSDT' AND c.open_time='2026-10-12 01:00:00') OR (c.symbol='DOGEUSDT' AND c.open_time='2026-10-12 03:00:00') OR (c.symbol='SHIBUSDT' AND c.open_time='2026-10-12 05:00:00') OR (c.symbol='ACEUSDT' AND c.open_time='2026-10-12 08:00:00'))) ORDER BY c.symbol, c.interval_code, c.open_time LIMIT 30;